256	}
257	switch (ChaosStopwatch.CheckInterval(attackStopwatchID))
258	{
259	case StopwatchState.Running:
260	attackCol.enabled = false;
261	break;
262	case StopwatchState.Ready:
263	if (ChaosStopwatch.CheckInterval(attackStopwatchID, getCharge: false) != StopwatchState.Done)
264	{
265	attackCol.enabled = true;
266	}
267	break;
268	case StopwatchState.Done:
269	{
270	attackCol.enabled = false;
271	durationCompleted = true;
272	fireShapeMod.radius = 0.25f;
273	fireShapeMod.arcMode = ParticleSystemShapeMultiModeValue.Random;
274	fireMainMod.startSpeed = 3f;
