292	{
293	expandLerpVal = expandStopwatch.TimePercentage;
294	fireShapeMod.arcSpeed = Mathf.Lerp(0.5f, 2f, expandLerpVal);
295	lerpedRadius = Mathf.Lerp(minRadius, maxRadius, expandLerpVal);
296	fireShapeMod.radius = lerpedRadius - 0.5f;
297	attackCol.radius = lerpedRadius;
298	expandCompleted = expandLerpVal >= 1f;
299	}
300	}
